:root{color-scheme:light;--surface-1:#fcfcfb;--plane:#f9f9f7;--ink-1:#0b0b0b;--ink-2:#52514e;--ink-muted:#898781;--grid:#e1e0d9;--axis:#c3c2b7;--border:rgba(11,11,11,.10);--series-1:#2a78d6;--series-2:#eb6834;--good-text:#006300;--critical:#d03b3b;--chip:#f0efec;--lockbg:rgba(11,11,11,.035)}
:root[data-theme="dark"]{color-scheme:dark;--surface-1:#1a1a19;--plane:#0d0d0d;--ink-1:#fff;--ink-2:#c3c2b7;--ink-muted:#898781;--grid:#2c2c2a;--axis:#383835;--border:rgba(255,255,255,.10);--series-1:#3987e5;--series-2:#d95926;--good-text:#0ca30c;--critical:#d03b3b;--chip:#262624;--lockbg:rgba(255,255,255,.04)}
*{box-sizing:border-box}
body{margin:0;background:var(--plane);color:var(--ink-1);font-family:system-ui,-apple-system,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;font-size:15px;line-height:1.5}
.wrap{max-width:820px;margin:0 auto;padding:14px 14px 90px}
header.top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}
header.top>.row{flex-shrink:0}#btnRefresh{white-space:nowrap}
h1{font-size:19px;margin:0}
.sub{color:var(--ink-2);font-size:12px}
.btn{background:var(--surface-1);color:var(--ink-1);border:1px solid var(--border);border-radius:10px;padding:9px 14px;font-size:15px;cursor:pointer;font-family:inherit}
.btn.primary{background:var(--series-1);border-color:transparent;color:#fff}
.btn.danger{color:var(--critical)}
.btn.sm{padding:5px 10px;font-size:13px}
.btn.big{width:100%;padding:13px;font-size:16px;font-weight:600}
.btn:disabled{opacity:.45;cursor:not-allowed}
.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.kpis{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px}
.kpi{background:var(--surface-1);border:1px solid var(--border);border-radius:12px;padding:12px 14px}
