.top-holdings-rank{color:var(--ink-muted)}.top-holdings-ticker{font-weight:650;overflow-wrap:anywhere}.top-holdings-value{font-weight:600;white-space:nowrap}.top-holdings-weight{min-width:43px;text-align:right;color:var(--ink-2);white-space:nowrap}
