.bench-formula{font-size:10px;color:var(--ink-muted);margin:6px 1px 10px}
.bench-expl{margin:0}
.bench-expl>summary{display:flex;align-items:center;justify-content:space-between;width:100%;border:1px solid var(--border);border-radius:9px;background:var(--surface-1);padding:8px 10px;font-weight:600}
