*{box-sizing:border-box}
body{margin:0;background:var(--plane);color:var(--ink-1);font-family:system-ui,-apple-system,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;font-size:15px;line-height:1.5}
.wrap{max-width:820px;margin:0 auto;padding:14px 14px 90px}
header.top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}
header.top>.row{flex-shrink:0}#btnRefresh{white-space:nowrap}
h1{font-size:19px;margin:0}
.sub{color:var(--ink-2);font-size:12px}
.btn{background:var(--surface-1);color:var(--ink-1);border:1px solid var(--border);border-radius:10px;padding:9px 14px;font-size:15px;cursor:pointer;font-family:inherit}
.btn.primary{background:var(--series-1);border-color:transparent;color:#fff}
.btn.danger{color:var(--critical)}
.btn.sm{padding:5px 10px;font-size:13px}
.btn.big{width:100%;padding:13px;font-size:16px;font-weight:600}
.btn:disabled{opacity:.45;cursor:not-allowed}
.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.kpis{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px}
.kpi{background:var(--surface-1);border:1px solid var(--border);border-radius:12px;padding:12px 14px}
.kpi.wide{grid-column:1/-1}
.kpi .lab{font-size:12px;color:var(--ink-2);margin-bottom:4px}
.kpi .val{font-size:22px;font-weight:600;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.kpi .note{font-size:11px;color:var(--ink-muted);margin-top:3px}
.mix{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:8px 0 4px;padding:8px 0 6px;border-top:1px solid var(--grid)}
.mix.two{grid-template-columns:repeat(2,1fr)}
.mix.gold{grid-template-columns:repeat(2,minmax(0,1fr))}
.mix .k{font-size:11px;color:var(--ink-2)}
.mix .v{font-size:15px;font-weight:600;font-variant-numeric:tabular-nums;letter-spacing:-.01em;white-space:nowrap}
.mix .p{font-size:11px;color:var(--ink-muted);margin-left:3px;font-weight:400}
.top-holdings{margin:9px 0 0;padding:8px 0 2px;border-top:1px solid var(--grid)}
.top-holdings-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:2px;font-size:11px;color:var(--ink-2)}
.top-holdings-row{display:grid;grid-template-columns:18px minmax(0,1fr) auto auto;align-items:baseline;gap:7px;padding:3px 0;font-size:12px;font-variant-numeric:tabular-nums}
.top-holdings-rank{color:var(--ink-muted)}.top-holdings-ticker{font-weight:650;overflow-wrap:anywhere}.top-holdings-value{font-weight:600;white-space:nowrap}.top-holdings-weight{min-width:43px;text-align:right;color:var(--ink-2);white-space:nowrap}
.top-holdings+.mix{border-top:0;margin-top:2px;padding-top:4px}
.rr{display:flex;justify-content:space-between;align-items:baseline;gap:10px;padding:5px 0;font-size:14px}
.rr span{color:var(--ink-2)}
.rr b{font-size:19px;font-weight:600;font-variant-numeric:tabular-nums;letter-spacing:-.01em}
.pos{color:var(--good-text)} .neg{color:var(--critical)}
.gate{border:1px solid var(--critical);background:rgba(208,59,59,.07);color:var(--critical);border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:13px;line-height:1.55}
.gate b{display:block;font-size:14px;margin-bottom:2px}
.gate ul{margin:4px 0 0;padding-left:18px}
.hold{color:var(--critical)}
.expl{margin:0 0 10px}
.expl>summary{display:inline-block;cursor:pointer;list-style:none;font-size:12px;color:var(--ink-2);background:var(--chip);border-radius:999px;padding:3px 11px;user-select:none}
.expl>summary::-webkit-details-marker{display:none}
.expl>summary::after{content:" ▾"}
.expl[open]>summary::after{content:" ▴"}
.expl>.hint{margin-top:7px}
.bench-title{font-size:12px;font-weight:600;color:var(--ink-2);margin:12px 0 6px}
.bench-table-wrap{overflow:hidden;border:1px solid var(--grid);border-radius:10px;background:var(--plane)}
.bench-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;font-variant-numeric:tabular-nums}
.bench-table th,.bench-table td{padding:8px 7px;border-bottom:1px solid var(--grid);vertical-align:middle;text-align:left}
.bench-table tr:last-child td{border-bottom:none}
.bench-table th{color:var(--ink-muted);font-size:10px;font-weight:600;background:var(--lockbg)}
.bench-table th:nth-child(1),.bench-table td:nth-child(1){width:31%}
.bench-table th:nth-child(2),.bench-table td:nth-child(2){width:27%;text-align:right;white-space:nowrap}
.bench-table th:nth-child(3),.bench-table td:nth-child(3){width:42%;text-align:right}
.bench-table .scenario{font-weight:600;color:var(--ink-1)}
.bench-table .tag{display:block;color:var(--ink-muted);font-size:10px;font-weight:400}
.bench-table .end-val{font-weight:600;color:var(--ink-1)}
.bench-table .gap-dir{display:block;color:var(--ink-2);font-size:10px}
.bench-table .gap-val{display:block;font-weight:600;white-space:nowrap}
.bench-formula{font-size:10px;color:var(--ink-muted);margin:6px 1px 10px}
.bench-expl{margin:0}
.bench-expl>summary{display:flex;align-items:center;justify-content:space-between;width:100%;border:1px solid var(--border);border-radius:9px;background:var(--surface-1);padding:8px 10px;font-weight:600}
.bench-expl>summary::after{margin-left:8px}
.bench-expl>.hint{line-height:1.55}
.bench-points{margin:8px 0 0;padding-left:22px}
.bench-points li{margin:0 0 7px;padding-left:2px}
.bench-points li:last-child{margin-bottom:0}
@media(max-width:430px){
  .bench-table{font-size:11px}
  .bench-table th,.bench-table td{padding:8px 5px}
  .bench-table th{font-size:9px}
  .bench-table th:nth-child(1),.bench-table td:nth-child(1){width:29%}
  .bench-table th:nth-child(2),.bench-table td:nth-child(2){width:28%}
  .bench-table th:nth-child(3),.bench-table td:nth-child(3){width:43%}
}
/* compact-comparison-tables:styles */
.bench-table.metric-table th,.bench-table.metric-table td{padding:7px 6px;vertical-align:top}
.bench-table.metric-table th:nth-child(1),.bench-table.metric-table td:nth-child(1){width:26%}
.bench-table.metric-table th:nth-child(2),.bench-table.metric-table td:nth-child(2){width:48%;text-align:left;white-space:normal;overflow-wrap:anywhere}
.bench-table.metric-table th:nth-child(3),.bench-table.metric-table td:nth-child(3){width:26%;text-align:right}
.metric-table .metric-value{font-size:14px;font-weight:650;white-space:nowrap}
.metric-table .metric-method{font-weight:500;color:var(--ink-2)}
.bench-table.drawdown-table th:nth-child(1),.bench-table.drawdown-table td:nth-child(1){width:15%}
.bench-table.drawdown-table th:nth-child(2),.bench-table.drawdown-table td:nth-child(2){width:26%;text-align:right;white-space:nowrap}
.bench-table.drawdown-table th:nth-child(3),.bench-table.drawdown-table td:nth-child(3){width:59%;text-align:left;overflow-wrap:anywhere;line-height:1.5}
.drawdown-table .episode-recovery{display:block;color:var(--ink-2);margin-top:3px}
@media(max-width:430px){.metric-table .metric-value{font-size:12px}.drawdown-table .episode-detail{font-size:10px}.bench-table.metric-table th,.bench-table.metric-table td{padding:7px 5px}}
.amt{color:var(--ink-1);font-weight:600}
nav.tabs[hidden]{display:none}
nav.tabs{display:flex;gap:2px;border-bottom:1px solid var(--border);margin-bottom:12px}
nav.tabs button{flex:1;background:none;border:none;border-bottom:2px solid transparent;color:var(--ink-2);padding:10px 4px;font-size:15px;cursor:pointer;font-family:inherit;margin-bottom:-1px}
nav.tabs button.on{color:var(--ink-1);border-bottom-color:var(--series-1);font-weight:600}
nav.tabs.hidden{display:none}
section.pane{display:none} section.pane.on{display:block}
.card{background:var(--surface-1);border:1px solid var(--border);border-radius:12px;padding:14px;margin-bottom:12px}
.card h2{font-size:15px;margin:0 0 4px}
.card .hint{font-size:12px;color:var(--ink-2);margin:0 0 10px}
/* ratio-presentation:v1 — display only; the reviewed model/crypto factories stay unchanged. */
#p-ratio{min-width:0}#p-ratio .card,#p-ratio details,#p-ratio code{min-width:0;overflow-wrap:anywhere}
#p-ratio p{font-size:12px;color:var(--ink-2);line-height:1.6;margin:6px 0}
#p-ratio .ratio-intro{padding:10px 12px}#ratioNotice{color:var(--ink-1)!important;font-weight:600}
.ratio-gold{display:flex;flex-wrap:wrap;gap:2px 12px}.ratio-gold span{display:block}
.ratio-report-meta{margin:4px 0}.ratio-report-meta p{display:flex;gap:8px;margin:6px 0!important}
.ratio-asset-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:12px 0}
.ratio-asset-grid>.kpi{min-width:0;margin:0;padding:10px;background:var(--plane)}
.ratio-asset-grid .lab{font-size:12px;font-weight:500;color:var(--ink-2);display:block}
.ratio-asset-pct{font-size:23px;font-weight:650;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.ratio-asset-total{display:block;font-size:11px;color:var(--ink-2);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.ratio-asset-grid [role=meter]{height:5px!important;margin:8px 0 0!important;background:var(--grid)!important;border-radius:4px;overflow:hidden}
.ratio-asset-grid [role=meter]>span{background:var(--series-1)!important}
.ratio-exposure-grid,.ratio-plan-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.ratio-exposure-grid{margin:12px 0;align-items:start}.ratio-exposure-grid>section{min-width:0;border:1px solid var(--border);border-radius:10px;padding:10px;background:var(--plane)}
.ratio-exposure-grid h3{font-size:13px;margin:0 0 4px;overflow-wrap:anywhere}
.ratio-holding-list{margin-top:8px}.ratio-holding-row{padding:9px 0;border-top:1px solid var(--grid)}
.ratio-holding-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px;font-size:12px;font-variant-numeric:tabular-nums}
.ratio-holding-name{min-width:0;font-weight:600;overflow-wrap:anywhere}.ratio-holding-amount{flex:none;white-space:nowrap;font-weight:600}
.ratio-holding-weights{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 12px;margin:5px 0 0;font-size:11px;font-variant-numeric:tabular-nums}
.ratio-holding-weights>div{display:flex;justify-content:space-between;gap:5px;align-items:baseline}.ratio-holding-weights dt{color:var(--ink-muted)}.ratio-holding-weights dd{margin:0;white-space:nowrap;color:var(--ink-2)}
#p-ratio .ratio-composition{margin-top:4px;border-top:1px dashed var(--grid)}#p-ratio .ratio-composition summary{font-size:11px;min-height:44px}
.ratio-constituents{list-style:none;margin:0;padding:0 0 2px}.ratio-constituents li{display:flex;gap:7px;padding:7px 0;border-top:1px solid var(--grid);font-size:12px;line-height:1.65;color:var(--ink-2)}
.ratio-constituent-number,.ratio-note-number{flex:none;color:var(--ink-muted);font-variant-numeric:tabular-nums}.ratio-constituent-text{min-width:0;overflow-wrap:anywhere}
#p-ratio .ratio-explanation{border:1px solid var(--border);border-radius:10px;padding:0 12px;margin-top:8px;background:var(--surface-1)}
#p-ratio .ratio-explanation>summary{font-weight:600;color:var(--ink-1)}#p-ratio .ratio-explanation>p{display:flex;gap:8px;margin:8px 0}.ratio-note-text{min-width:0;overflow-wrap:anywhere}
.ratio-plan-grid>.card{min-width:0;margin-bottom:12px}
#p-ratio table{width:100%;table-layout:fixed;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums;margin:8px 0}
#p-ratio th,#p-ratio td{padding:8px 5px;border-bottom:1px solid var(--grid);vertical-align:top;text-align:right;overflow-wrap:anywhere;word-break:normal;white-space:normal}
#p-ratio th{font-size:10px;font-weight:500;color:var(--ink-2)}#p-ratio td{font-weight:550}
#p-ratio th:first-child,#p-ratio td:first-child{width:40%;text-align:left;font-weight:500}
#p-ratio tbody tr:last-child td{border-bottom:0}
.ratio-key-status{font-size:12px;line-height:1.6;overflow-wrap:anywhere}#p-ratio td details{font-weight:400}#p-ratio td summary{font-size:11px;text-align:left}#p-ratio td details ul{padding-left:16px;text-align:left}
.ratio-coverage{border-top:1px solid var(--grid);padding-top:8px}.ratio-coverage-list{list-style:none;margin:0;padding:0}
.ratio-coverage-list li{font-size:12px;line-height:1.6;color:var(--ink-2);margin:4px 0;overflow-wrap:anywhere}
#p-ratio .ratio-caveats{border-left:3px solid var(--axis);padding:2px 10px;margin-bottom:12px}
#p-ratio details{font-size:12px;margin-top:8px}#p-ratio summary{display:flex;align-items:center;gap:8px;min-height:44px;cursor:pointer;color:var(--ink-2);list-style:none}
#p-ratio summary::-webkit-details-marker{display:none}#p-ratio summary::before{content:"▸";font-size:11px;color:var(--ink-muted)}#p-ratio details[open]>summary::before{content:"▾"}
#p-ratio summary:focus-visible,#p-ratio .btn:focus-visible{outline:2px solid var(--series-1);outline-offset:3px}
.ratio-tools>details+details{border-top:1px solid var(--grid)}#p-ratio .ratio-tools label{display:block;margin:10px 0 4px;font-size:12px;color:var(--ink-2)}
#p-ratio input[type=checkbox]{width:auto;margin-right:7px}#p-ratio .btn{min-height:44px;max-width:100%;white-space:normal;margin:4px 4px 4px 0}
@media(max-width:600px){.ratio-asset-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ratio-exposure-grid,.ratio-plan-grid{grid-template-columns:minmax(0,1fr)}#p-ratio .ratio-tools .btn{width:100%;margin-right:0}}
@media(max-width:360px){#p-ratio th,#p-ratio td{padding:7px 3px;font-size:11px}#p-ratio th{font-size:10px}.ratio-asset-pct{font-size:21px}}
.ratio-holding-accounts{display:block;color:var(--ink-2);font-size:11px;line-height:1.5;margin:2px 0 4px}.ratio-stock-allocation{margin-bottom:10px}.ratio-stock-allocation h2{margin-bottom:4px}
.ratio-distribution-category{margin-top:12px}.ratio-distribution-category h3{font-size:12px;margin:0 0 6px}.ratio-distribution-account{padding:6px 0;border-top:1px solid var(--grid)}
.ratio-distribution-account h4,.ratio-fund-holding{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:baseline;gap:10px;font-size:11px;line-height:1.6;margin:0;padding:4px 0}
.ratio-distribution-account h4 span:first-child,.ratio-fund-holding-name{min-width:0;overflow-wrap:anywhere}.ratio-distribution-account h4 span:last-child,.ratio-fund-holding>span:last-child{white-space:nowrap;font-variant-numeric:tabular-nums}.ratio-distribution-account ul{list-style:none;margin:0;padding:0}

#p-ratio .ratio-six-allocation th:first-child,#p-ratio .ratio-six-allocation td:first-child{width:24%}
#p-ratio .ratio-six-allocation th:nth-child(2),#p-ratio .ratio-six-allocation td:nth-child(2){width:39%}
#p-ratio .ratio-six-allocation td{font-size:12px}.ratio-asset-sum{font-weight:600}
#p-ratio .ratio-asset-notes h3{font-size:12px;margin:10px 0 4px}.ratio-asset-notes ul{list-style:none;margin:0;padding:0}.ratio-asset-notes li{display:flex;justify-content:space-between;align-items:baseline;gap:10px;padding:5px 0;border-bottom:1px solid var(--grid)}.ratio-asset-notes li span:first-child{min-width:0;overflow-wrap:anywhere}.ratio-asset-notes li span:last-child{flex-shrink:0;font-variant-numeric:tabular-nums}
@media(max-width:400px){#p-ratio .ratio-six-allocation td{font-size:11px;padding:8px 3px}}
.fund-doc-list{display:grid;gap:10px}.fund-doc-list details{border:1px solid var(--border);border-radius:10px;padding:10px}.fund-doc-list summary{cursor:pointer;font-weight:650}.fund-doc-meta{font-size:12px;color:var(--ink-2);margin:4px 0 8px}.fund-doc-body{white-space:pre-wrap;word-break:break-word;font:inherit;font-size:13px;max-height:320px;overflow:auto;background:var(--lockbg);border-radius:8px;padding:10px}.fund-doc-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}
.fund-archive-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.fund-archive-head>div{min-width:0}.fund-archive-head .btn{flex:0 0 auto}.fund-role-list{display:grid;gap:7px;margin:10px 0 12px}.fund-role{display:flex;justify-content:space-between;gap:12px;padding:8px 10px;border-radius:8px;background:var(--lockbg);font-size:12px}.fund-role span{color:var(--ink-2)}.fund-role b{text-align:right;max-width:58%;overflow-wrap:anywhere}.fund-archive-empty{padding:12px 0 2px;color:var(--ink-muted);font-size:13px}
.fund-print-sheet{display:none}
.feeCard{border:1px solid var(--border);border-radius:12px;padding:10px;margin-top:10px;background:var(--lockbg)}
.feeCard .fr{display:flex;gap:8px;align-items:center;margin-top:8px}.feeCard .fr:first-child{margin-top:0}
.feeCard input,.feeCard select{min-width:0;font-size:16px;padding:8px}
.feeSum{display:flex;justify-content:space-between;margin-top:12px;font-weight:600;font-size:14px}.feeSum .l{font-weight:400;color:var(--ink-muted)}
input,select,textarea{background:var(--plane);color:var(--ink-1);border:1px solid var(--border);border-radius:8px;padding:9px 10px;font-size:16px;font-family:inherit;width:100%;font-variant-numeric:tabular-nums}
input:disabled,select:disabled,textarea:disabled{background:var(--lockbg);color:var(--ink-2);border-style:dashed}
input[type=number]{text-align:right}
label.f{display:block;font-size:12px;color:var(--ink-2);margin-bottom:4px}
.grid{display:grid;gap:10px;grid-template-columns:1fr 1fr}
.grid .full{grid-column:1/-1}
.res{background:var(--plane);border:1px solid var(--grid);border-radius:10px;padding:10px 12px}
.res .line{display:flex;justify-content:space-between;gap:12px;padding:5px 0;font-size:14px;font-variant-numeric:tabular-nums}
.res .line.tot{border-top:1px solid var(--axis);margin-top:4px;padding-top:8px;font-weight:600}
.res .line span:first-child{color:var(--ink-2);text-align:left}
.badge{font-size:11px;padding:2px 8px;border-radius:20px;background:var(--chip);color:var(--ink-2);border:1px solid var(--border);white-space:nowrap}
.badge.est{background:rgba(250,178,25,.16);color:var(--ink-1);border-color:rgba(250,178,25,.55)}
.badge.hwm{background:rgba(235,104,52,.14);border-color:rgba(235,104,52,.45)}
.badge.ok{background:rgba(12,163,12,.14);border-color:rgba(12,163,12,.45)}
.legend{display:flex;gap:14px;font-size:12px;color:var(--ink-2);margin-bottom:6px;flex-wrap:wrap}
.cwrap{position:relative;touch-action:pan-y}
.tip{position:absolute;display:none;pointer-events:none;background:var(--surface-1);border:1px solid var(--border);border-radius:8px;padding:7px 9px;font-size:11px;line-height:1.5;box-shadow:0 6px 18px rgba(0,0,0,.14);white-space:nowrap;font-variant-numeric:tabular-nums;z-index:5}
.legend i{width:11px;height:11px;border-radius:3px;display:inline-block;margin-right:5px;vertical-align:-1px}svg{display:block;width:100%;height:auto;overflow:visible}
.empty{color:var(--ink-muted);font-size:13px;padding:14px;text-align:center}
.warn{background:rgba(250,178,25,.12);border:1px solid rgba(250,178,25,.45);border-radius:10px;padding:10px 12px;font-size:13px;margin-bottom:10px}
.info{background:rgba(42,120,214,.09);border:1px solid rgba(42,120,214,.35);border-radius:10px;padding:10px 12px;font-size:13px;margin-bottom:10px}
.small{font-size:12px;color:var(--ink-2)}
code{background:var(--chip);padding:1px 5px;border-radius:4px;font-size:12px}
.del{color:var(--critical);cursor:pointer;background:none;border:none;font-size:18px;padding:0 6px;line-height:1}
.ovl{position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:200;display:none;align-items:flex-start;justify-content:center;padding:6vh 12px 12px;overflow:auto}
.ovl.on{display:flex}
.modal{border:1px solid var(--border);border-radius:14px;background:var(--surface-1);color:var(--ink-1);max-width:460px;width:100%;padding:16px;box-shadow:0 18px 50px rgba(0,0,0,.3)}
.toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%);background:var(--ink-1);color:var(--surface-1);padding:9px 16px;border-radius:8px;font-size:13px;z-index:300;opacity:0;transition:opacity .18s;pointer-events:none;max-width:86%;text-align:center}
